//! Authentication for the desktop app's control channel (`filmcraft --control <port>`).
//!
//! The app writes a random token to `<data dir>/control-<port>.token` (owner-only on Unix) when the
//! control server starts; every connection must first send
//! `{"method":"auth","params":{"token":"…"}}`. `FILMCRAFT_CONTROL_TOKEN` sets the token explicitly
//! (the app uses it instead of a random one, and clients send it instead of reading the file).
//! Clients ([`client_token`]) and the server share the file name and the comparison here; the
//! token itself is generated by the app. See `docs/control-protocol.md`.

use std::path::{Path, PathBuf};

/// Environment variable holding an explicit control token (server and clients).
pub const TOKEN_ENV: &str = "FILMCRAFT_CONTROL_TOKEN";
/// The method a connection's first request must use.
pub const AUTH_METHOD: &str = "auth";
/// Longest token accepted from the environment or a token file.
pub const MAX_TOKEN_LEN: usize = 1024;

/// The token file of the control server on `port` in `data_dir`.
pub fn token_path(data_dir: &Path, port: u16) -> PathBuf {
    data_dir.join(format!("control-{port}.token"))
}

/// A usable token: non-empty, bounded and printable ASCII without spaces (it travels in JSON).
pub fn valid_token(t: &str) -> bool {
    !t.is_empty() && t.len() <= MAX_TOKEN_LEN && t.bytes().all(|b| b.is_ascii_graphic())
}

/// The explicit token from `FILMCRAFT_CONTROL_TOKEN`, if set and valid.
pub fn env_token() -> Option<String> {
    let v = std::env::var(TOKEN_ENV).ok()?;
    let v = v.trim();
    valid_token(v).then(|| v.to_string())
}

/// Read the token file at `path` (bounded; None when missing or malformed).
pub fn read_token_file(path: &Path) -> Option<String> {
    use std::io::Read;
    let f = std::fs::File::open(path).ok()?;
    let mut s = String::new();
    f.take(MAX_TOKEN_LEN as u64 + 2).read_to_string(&mut s).ok()?;
    let t = s.trim();
    valid_token(t).then(|| t.to_string())
}

/// The token a client should present to the app on `port`: `FILMCRAFT_CONTROL_TOKEN`, else the
/// token file in the default data folder (`FILMCRAFT_DATA_DIR`, else the per-user one).
pub fn client_token(port: u16) -> Option<String> {
    env_token().or_else(|| read_token_file(&token_path(&crate::autosave::default_data_dir()?, port)))
}

/// Write `token` to `path`, readable only by the current user on Unix (created with mode 0600; a
/// stale file or a planted symlink in its place is removed first and never followed).
pub fn write_token_file(path: &Path, token: &str) -> std::io::Result<()> {
    use std::io::Write;
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir)?;
    }
    match std::fs::remove_file(path) {
        Ok(()) => {}
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
        Err(e) => return Err(e),
    }
    let mut o = std::fs::OpenOptions::new();
    o.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        o.mode(0o600);
    }
    let mut f = o.open(path)?;
    f.write_all(token.as_bytes())?;
    f.write_all(b"\n")?;
    f.sync_all()
}

/// Compare two tokens in time independent of where they differ.
pub fn tokens_match(given: &str, expected: &str) -> bool {
    let (a, b) = (given.as_bytes(), expected.as_bytes());
    let mut diff = (a.len() ^ b.len()) as u64;
    for i in 0..a.len().max(b.len()) {
        let x = a.get(i).copied().unwrap_or(0);
        let y = b.get(i).copied().unwrap_or(0);
        diff |= u64::from(x ^ y);
    }
    diff == 0
}

/// Lowercase hex of `bytes` (for turning random bytes into a token).
pub fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn compare() {
        assert!(tokens_match("abc", "abc"));
        assert!(!tokens_match("abc", "abd"));
        assert!(!tokens_match("ab", "abc"));
        assert!(!tokens_match("", "abc"));
        assert!(!tokens_match("abc\0", "abc"));
    }

    #[test]
    fn validity() {
        assert!(valid_token("0123abcd"));
        assert!(!valid_token(""));
        assert!(!valid_token("a b"));
        assert!(!valid_token(&"a".repeat(MAX_TOKEN_LEN + 1)));
    }

    #[test]
    fn token_file_round_trip_and_permissions() {
        let dir = std::env::temp_dir().join(format!("fc-control-token-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let p = token_path(&dir, 9876);
        // a stale world-readable file is replaced, not reused
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(&p, "old").unwrap();
        write_token_file(&p, "deadbeef").unwrap();
        assert_eq!(read_token_file(&p).as_deref(), Some("deadbeef"));
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            assert_eq!(std::fs::metadata(&p).unwrap().permissions().mode() & 0o777, 0o600);
            // a symlink planted at the token path is not followed
            let target = dir.join("victim");
            std::fs::write(&target, "keep").unwrap();
            std::fs::remove_file(&p).unwrap();
            std::os::unix::fs::symlink(&target, &p).unwrap();
            write_token_file(&p, "cafe").unwrap();
            assert_eq!(std::fs::read_to_string(&target).unwrap(), "keep");
            assert_eq!(read_token_file(&p).as_deref(), Some("cafe"));
        }
        std::fs::write(&p, "has space").unwrap();
        assert_eq!(read_token_file(&p), None);
        let _ = std::fs::remove_dir_all(&dir);
    }
}
